#define _POSIX_C_SOURCE 200809L
#include <glob.h>
#include <inttypes.h>
#include <openssl/evp.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <zstd.h>

enum { RAM_SIZE=0x200000, ACTORS=40, STRIDE=0x84 };
typedef struct {const uint8_t*p;size_t n,o;} Buf;
typedef struct {uint32_t base;int score,programs,backlinks;} Candidate;
typedef struct {int valid;int32_t x,y,z;} Previous;
typedef struct {uint64_t samples,moved_x,moved_y,moved_z,exact_x,exact_y,exact_z,state_x,state_y,state_z,state_samples;int32_t min20,max20;uint64_t nonzero20;} Stats;
static void fail(const char*s){fprintf(stderr,"d02_actor20: %s\n",s);exit(2);}static void*xmalloc(size_t n){void*p=malloc(n?n:1);if(!p)fail("out of memory");return p;}
static const uint8_t*take(Buf*b,size_t n){if(n>b->n-b->o)fail("truncated record");const uint8_t*p=b->p+b->o;b->o+=n;return p;}static uint8_t u8(Buf*b){return*take(b,1);}static uint16_t u16(Buf*b){const uint8_t*p=take(b,2);return(uint16_t)(p[0]|p[1]<<8);}static uint32_t u32(Buf*b){const uint8_t*p=take(b,4);return(uint32_t)p[0]|(uint32_t)p[1]<<8|(uint32_t)p[2]<<16|(uint32_t)p[3]<<24;}static uint64_t u64(Buf*b){uint64_t lo=u32(b),hi=u32(b);return lo|hi<<32;}
static uint32_t ld32(const uint8_t*p){return(uint32_t)p[0]|(uint32_t)p[1]<<8|(uint32_t)p[2]<<16|(uint32_t)p[3]<<24;}static int16_t ld16s(const uint8_t*p){return(int16_t)(p[0]|p[1]<<8);}static int32_t s32(const uint8_t*p){return(int32_t)ld32(p);}
static uint8_t*read_file(const char*path,size_t*n){FILE*f=fopen(path,"rb");if(!f){perror(path);exit(2);}fseek(f,0,SEEK_END);long z=ftell(f);rewind(f);uint8_t*p=xmalloc((size_t)z);if(fread(p,1,(size_t)z,f)!=(size_t)z)fail("read");fclose(f);*n=(size_t)z;return p;}
static uint8_t*decomp(const char*path,size_t*n){size_t in_n;uint8_t*in=read_file(path,&in_n);unsigned long long z=ZSTD_getFrameContentSize(in,in_n);if(z==ZSTD_CONTENTSIZE_ERROR||z==ZSTD_CONTENTSIZE_UNKNOWN||z>SIZE_MAX)fail("zstd size");uint8_t*out=xmalloc((size_t)z);size_t got=ZSTD_decompress(out,(size_t)z,in,in_n);free(in);if(ZSTD_isError(got)||got!=(size_t)z)fail("zstd decode");*n=got;return out;}
static int sha_ok(const uint8_t*p,size_t n,const uint8_t expected[32]){uint8_t got[32];size_t gn=0;if(!EVP_Q_digest(NULL,"SHA256",NULL,p,n,got,&gn)||gn!=32)fail("sha");return!memcmp(got,expected,32);}static int kptr(uint32_t p){return p>=0x80010000&&p<0x80200000;}static int progptr(uint32_t p){return p>=0x80070000&&p<0x80080000;}static int coord(int32_t v){return v>-8000000&&v<8000000;}
static Candidate score_base(const uint8_t*ram,uint32_t base){Candidate c={base,0,0,0};for(unsigned i=0;i<ACTORS;i++){uint32_t o=base+i*STRIDE;if(o+STRIDE>RAM_SIZE)return(Candidate){base,-999,0,0};uint32_t prog=ld32(ram+o+0x70),back=ld32(ram+o+0x80);int hp=ld16s(ram+o+0x6e);if(!prog||progptr(prog)){c.score+=2;if(prog)c.programs++;}if(!back||kptr(back)){c.score+=2;if(back)c.backlinks++;}if(hp>=-32&&hp<=1024)c.score++;if(coord(s32(ram+o))&&coord(s32(ram+o+4))&&coord(s32(ram+o+8)))c.score++;}c.score+=c.programs*3+c.backlinks*2;return c;}
static int cmpcand(const void*a,const void*b){const Candidate*x=a,*y=b;return y->score-x->score;}
static uint32_t discover(const uint8_t*ram){Candidate top[0x20000/4];size_t n=0;for(uint32_t b=0x90000;b+ACTORS*STRIDE<0xb0000;b+=4)top[n++]=score_base(ram,b);qsort(top,n,sizeof(*top),cmpcand);puts("POOL_CANDIDATES");for(unsigned i=0;i<8;i++)printf("  base=0x%08x score=%d programs=%d backlinks=%d\n",0x80000000u+top[i].base,top[i].score,top[i].programs,top[i].backlinks);return top[0].base;}
static int occupied(const uint8_t*r){return ld32(r)!=0;}
static void sample(const uint8_t*ram,uint32_t base,Previous prev[ACTORS],Stats*s,int first){for(unsigned i=0;i<ACTORS;i++){const uint8_t*r=ram+base+i*STRIDE;if(!occupied(r)){prev[i].valid=0;continue;}int32_t x=s32(r+4),y=s32(r+8),z=s32(r+0xc),vx=s32(r+0x1c),v20=s32(r+0x20),vz=s32(r+0x24);s->samples++;if(v20){s->nonzero20++;if(v20<s->min20)s->min20=v20;if(v20>s->max20)s->max20=v20;}if(!first&&prev[i].valid){int32_t dx=x-prev[i].x,dy=y-prev[i].y,dz=z-prev[i].z;if(dx){s->moved_x++;if(vx==dx)s->exact_x++;}if(dy){s->moved_y++;if(v20==dy)s->exact_y++;}if(dz){s->moved_z++;if(vz==dz)s->exact_z++;}}prev[i]=(Previous){1,x,y,z};}}
static void analyze(const char*dir){char pat[4096];snprintf(pat,sizeof(pat),"%s/chunks/*.zst",dir);glob_t g={0};if(glob(pat,0,NULL,&g)||!g.gl_pathc)fail("no chunks");uint8_t*dom[4]={0};uint32_t dsz[4]={0};Previous prev[ACTORS]={{0}};Stats st={.min20=INT32_MAX,.max20=INT32_MIN};uint32_t base=0;uint64_t records=0,checks=0,bad=0;uint32_t first_movie=0,last_movie=0;
 for(size_t fi=0;fi<g.gl_pathc;fi++){size_t n;uint8_t*raw=decomp(g.gl_pathv[fi],&n);Buf b={raw,n,0};if(memcmp(take(&b,8),"DSTCAP01",8))fail("magic");uint32_t ver=u32(&b);if(ver<1||ver>2)fail("version");(void)u32(&b);(void)u64(&b);uint32_t nr=u32(&b);for(uint32_t i=0;i<nr;i++){uint16_t z=u16(&b);(void)take(&b,z);}while(b.o<b.n){if(u8(&b)!=1)fail("tag");(void)u64(&b);(void)u64(&b);uint32_t movie=u32(&b);(void)u32(&b);(void)u32(&b);(void)take(&b,(size_t)nr*4);for(unsigned k=0;k<3;k++){uint32_t id=u32(&b),sz=u32(&b),np=u32(&b);const uint8_t*want=take(&b,32);if(id<1||id>3)fail("domain");if(!dom[id]){dom[id]=calloc(1,sz);dsz[id]=sz;}for(uint32_t p=0;p<np;p++){uint32_t o=u32(&b),l=u32(&b);if(o>sz||l>sz-o)fail("patch");memcpy(dom[id]+o,take(&b,l),l);}checks++;if(!sha_ok(dom[id],sz,want))bad++;}uint8_t*ram=NULL;for(unsigned id=1;id<=3;id++)if(dsz[id]==RAM_SIZE)ram=dom[id];if(!ram)fail("no ram");if(!records){base=discover(ram);first_movie=movie;}sample(ram,base,prev,&st,!records);uint64_t nf=u64(&b);for(uint64_t q=0;q<nf;q++){(void)u32(&b);if(ver==2){(void)u32(&b);(void)u64(&b);}else(void)u64(&b);}records++;last_movie=movie;}free(raw);}printf("CAPSULE %s\n  records=%"PRIu64" movie=%u..%u checks=%"PRIu64" mismatches=%"PRIu64" base=0x%08x\n",dir,records,first_movie,last_movie,checks,bad,0x80000000u+base);printf("  active_samples=%"PRIu64" field20_nonzero=%"PRIu64" field20_range=%d..%d\n",st.samples,st.nonzero20,st.nonzero20?st.min20:0,st.nonzero20?st.max20:0);printf("  frame_delta exact: X=%"PRIu64"/%"PRIu64" Y20=%"PRIu64"/%"PRIu64" Z=%"PRIu64"/%"PRIu64"\n",st.exact_x,st.moved_x,st.exact_y,st.moved_y,st.exact_z,st.moved_z);for(unsigned i=1;i<=3;i++)free(dom[i]);globfree(&g);}
int main(int argc,char**argv){if(argc<2){fprintf(stderr,"usage: %s CAPSULE...\n",argv[0]);return 2;}for(int i=1;i<argc;i++)analyze(argv[i]);return 0;}
